{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Nomegestrol acetate, the closest structural analogue sharing the 19-nor-17-acetoxy-17-acetyl-4-en-3-one core, has an absolute oral bioavailability of 63.4% in healthy women, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Chlormadinone acetate, a 17-acetoxy progestin, shows approximately 100% oral bioavailability in humans, indicating that this steroid class can achieve high systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Cyproterone acetate, another 17-acetoxy progestin, has almost complete absolute bioavailability (88% of dose) in humans, further supporting high oral bioavailability for structurally related progestins.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Medroxyprogesterone acetate has low oral bioavailability (<10%), but this is a 6-methylpregnane rather than a 19-norsteroid and is structurally more distant from the query, so it provides only limited contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Abiraterone acetate has estimated oral bioavailability below 10%, but its androstane scaffold and 3-acetate prodrug character are substantially different from the query's 19-norprogesterone core, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the closest structural analogue, nomegestrol acetate, and several other 17-acetoxy progestins show high absolute oral bioavailability, while the low-bioavailability analogues are structurally more distant or carry specific metabolic liabilities not shared by the query.",
